    risk.length ? `Current risk notes: ${risk.join("; ")}.` : undefined,
    "",
    "We will keep the position provisional until the above evidence is confirmed and linked to the voyage file.",
    "",
    "Regards,",
    "Operations Desk",
  ].filter(Boolean).join("\n");

  return {
