    fileNames.map(async (fileName) => {
      const parsed = parseMarkdownDocument(await readFileText(path.join(documentsRoot, fileName)));
      const frontMatter = frontMatterSchema.parse(parsed.frontMatter);
      return {
        ...frontMatter,
        fileName,
      };
    }),
  );
}

